# -*- coding: utf-8 -*-
TIER2_HEAD = '<b>【 แบบที่ 2 ▸ พื้นฐาน · กระชับ · ใช้ความเป็นฟังก์ชันลดของอาร์กโคไซน์แล้วคุมโดเมน (decreasing-function argument) 】</b>'
TIER2 = [
    r'🎯 <b>เหมาะกับ</b> เด็กปานกลางถึงเก่ง · รู้อยู่แล้วว่า $\arccos$ มีโดเมนจำกัดและเป็นฟังก์ชันลด เหลือแค่เดินสองชั้นให้ครบแล้วตัดกัน',
    r'<b>ขั้นที่ 1:</b> กันโดเมนก่อน โดยเงื่อนไขคร่อมก้อนที่ถูกป้อนเข้า $\arccos$ คือ $2x - 1$',
    r'⇒ $-1 \le 2x - 1 \le 1$ ⇒ บวก $1$ ทั้งสามช่อง ⇒ $0 \le 2x \le 2$ ⇒ หารด้วย $2$ ซึ่งเป็นบวก ⇒ $0 \le x \le 1$',
    r'<b>ขั้นที่ 2:</b> เขียนข้างขวาให้อยู่ในรูป $\arccos$ เหมือนข้างซ้าย',
    r'⇒ $\cos\dfrac{\pi}{3} = \dfrac{1}{2}$ และ $\dfrac{\pi}{3}$ อยู่ใน $[0 , \pi]$ ⇒ $\dfrac{\pi}{3} = \arccos\dfrac{1}{2}$ ⇒ อสมการกลายเป็น $\arccos(2x - 1) > \arccos\dfrac{1}{2}$',
    r'<b>ขั้นที่ 3:</b> ถอด $\arccos$ ออกทั้งสองข้าง · $\arccos$ เป็นฟังก์ชันลด เครื่องหมายจึงกลับด้าน',
    r'⇒ $2x - 1 < \dfrac{1}{2}$ ⇒ $2x < \dfrac{3}{2}$ ⇒ $x < \dfrac{3}{4}$',
    r'<b>ขั้นที่ 4:</b> ตัดผลสองชั้นเข้าหากัน แล้วตัดสินชนิดวงเล็บด้วยการแทนค่าที่ปลายทีละข้าง',
    r'⇒ $[0 , 1] \cap \left(-\infty , \dfrac{3}{4}\right) = \left[0 , \dfrac{3}{4}\right)$',
    r'⇒ ที่ $x = 0$ ได้ $\arccos(-1) = \pi$ ซึ่งมากกว่า $\dfrac{\pi}{3}$ จริง ⇒ ปลายซ้ายปิด · ที่ $x = \dfrac{3}{4}$ ได้ $\arccos\dfrac{1}{2} = \dfrac{\pi}{3}$ เท่ากันพอดี ⇒ ปลายขวาเปิด',
    r'⇒ เซตคำตอบคือ $\left[0 , \dfrac{3}{4}\right)$',
]
TIER3_HEAD = '<b>【 แบบที่ 3 ▸ ⚡ ประยุกต์ · แปลงเป็นอาร์กไซน์ด้วยเอกลักษณ์เติมเต็ม (complementary identity) 】</b>'
TIER3 = [
    r'⚡ <b>เหมาะกับ</b> เด็กที่พื้นฐานคณิตดี หรือเด็กที่ถนัด $\arcsin$ ซึ่งเป็นฟังก์ชันเพิ่ม มากกว่าการคอยระวังทิศของ $\arccos$',
    r'<b>ขั้นที่ 1:</b> ตั้ง $u = 2x - 1$ แล้วใช้ข้อสังเกตว่าอาร์กโคไซน์กับอาร์กไซน์ของค่าเดียวกันบวกกันได้มุมฉากเสมอ นั่นคือ $\arccos u + \arcsin u = \dfrac{\pi}{2}$',
    r'⇒ $\arccos u = \dfrac{\pi}{2} - \arcsin u$ ⇒ อสมการกลายเป็น $\dfrac{\pi}{2} - \arcsin u > \dfrac{\pi}{3}$',
    r'<b>ขั้นที่ 2:</b> ย้ายข้างให้เหลือ $\arcsin$ ตัวเดียว',
    r'⇒ $\arcsin u < \dfrac{\pi}{2} - \dfrac{\pi}{3} = \dfrac{\pi}{6}$',
    r'<b>ขั้นที่ 3:</b> ถอด $\arcsin$ ออก · $\arcsin$ เป็นฟังก์ชันเพิ่ม เครื่องหมายจึงไม่กลับ',
    r'⇒ $u < \sin\dfrac{\pi}{6} = \dfrac{1}{2}$ ⇒ $2x - 1 < \dfrac{1}{2}$ ⇒ $x < \dfrac{3}{4}$',
    r'<b>ขั้นที่ 4:</b> เอกลักษณ์นี้ใช้ได้เฉพาะเมื่อ $u$ อยู่ใน $[-1 , 1]$ จึงต้องใส่เงื่อนไขนั้นกลับเข้าไปแล้วตัดกัน',
    r'⇒ $-1 \le 2x - 1 \le 1$ ⇒ $0 \le x \le 1$ ⇒ $[0 , 1] \cap \left(-\infty , \dfrac{3}{4}\right) = \left[0 , \dfrac{3}{4}\right)$',
    r'<b>ข้อต่าง:</b> ไม่ต้องหยิบข้อเท็จจริงที่ว่า $\arccos$ เป็นฟังก์ชันลดมาใช้เลย และไม่ต้องเขียน $\dfrac{\pi}{3}$ ใหม่เป็น $\arccos\dfrac{1}{2}$ ก่อน ต่างจากแบบที่ 1–2 ที่ต้องกลับด้านอสมการด้วยเหตุผลเรื่องทิศของฟังก์ชัน ⇒ ที่นี่การกลับด้านย้ายไปอยู่ที่การย้ายข้างธรรมดา ซึ่งเป็นทักษะเดิมตั้งแต่อสมการเชิงเส้น · แลกกับต้องจำเอกลักษณ์เติมเต็มและค่า $\sin\dfrac{\pi}{6} = \dfrac{1}{2}$ ให้แม่น',
]
